import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx - 1, int(m.group(2)) - 1

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("Zip entries:")
    for n in names:
        print("  ", n)

    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels:
        rel_map[rel.get('Id')] = rel.get('Target')

    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{%s}t' % NS['m']))
            shared.append(text)

    sheet_order = []
    for sh in wb.find('m:sheets', NS):
        sheet_order.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))

    print("\nShared strings:", len(shared))
    for sh_name, rid in sheet_order:
        target = rel_map[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        print("\n=== Sheet:", sh_name, "->", target, "===")
        sh = ET.fromstring(z.read(target))
        rows = []
        for row in sh.find('m:sheetData', NS):
            r = []
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = None
                if v is not None:
                    if t == 's':
                        val = shared[int(v.text)]
                    elif t == 'inlineStr':
                        isv = c.find('m:is', NS)
                        val = ''.join(x.text or '' for x in isv.iter('{%s}t' % NS['m']))
                    else:
                        val = v.text
                if val is not None:
                    r.append((ref, val))
            rows.append(r)
        for row in rows:
            print(row)

